'use strict';
const initial = {
 html: `<main class="card">\n  <p class="eyebrow">HELLO, WORLD</p>\n  <h1>I'm Alex.</h1>\n  <p>I’m learning to build things for the web.</p>\n  <button id="hello">Say hello</button>\n  <p id="message" aria-live="polite"></p>\n</main>`,
 css: `body {\n  margin: 0; padding: 50px 24px;\n  font-family: Arial, sans-serif;\n  background: #f0f2fb; color: #25243a;\n}\n.card {\n  max-width: 420px; margin: auto;\n  background: white; padding: 32px;\n  border-radius: 20px;\n}\nh1 { font-size: 42px; letter-spacing: -2px; }\n.eyebrow { color: #4934d4; font-size: 12px; }\nbutton {\n  background: #4934d4; color: white;\n  border: 0; padding: 12px 20px;\n  border-radius: 8px; cursor: pointer;\n}`,
 js: `const button = document.querySelector('#hello');\nconst message = document.querySelector('#message');\n\nbutton.addEventListener('click', () => {\n  message.textContent = 'Hello! Thanks for visiting.';\n});`
};
const lessons = [
 {key:'html',name:'Structure',title:'Give your page a voice.',description:'HTML is the structure: a heading, an introduction, and a button. Start by making the words yours.',task:'Replace Alex with your name. Change the introduction to something about you. Then run your code.',location:'index.html · body',hint:'Paste this inside the <body> of an HTML file. Here, the recipe already handles that wrapper.',explanation:'<p><code>&lt;main&gt;</code> groups your main content.</p><p><code>&lt;h1&gt;</code> is the main heading; <code>&lt;p&gt;</code> is a paragraph.</p><p><code>class="card"</code> gives CSS a way to style this group. An <code>id</code> gives JavaScript a way to find one element.</p>',takeaway:'Content comes first.',summary:'HTML tells the browser what belongs on your page. Styling comes next.'},
 {key:'css',name:'Style',title:'Make it feel like you.',description:'CSS changes the look of the same content. A selector names the part you want to style; declarations describe its appearance.',task:'Change the button background from #4934d4 to #176b62. Try changing the card’s border-radius to 4px.',location:'index.html · style',hint:'Paste this inside a <style> tag in the <head>. Your HTML from recipe 1 stays in place.',explanation:'<p><code>body</code> styles the whole page. <code>.card</code> matches class="card" in your HTML.</p><p><code>background</code> sets a color. <code>padding</code> creates space inside an element.</p><p><code>border-radius</code> rounds the corners. Keep the colon and semicolon around each value.</p>',takeaway:'Same content. A different feeling.',summary:'CSS applies visual rules to the elements you already made. Your words stay in the HTML.'},
 {key:'js',name:'Interaction',title:'Give your button a job.',description:'JavaScript makes the page respond. This recipe finds the button and writes a message when someone clicks it.',task:'Change the greeting inside the quotes. Run your code, then click Say hello in the preview.',location:'index.html · script',hint:'Paste this inside a <script> tag just before </body>, after the HTML elements it needs.',explanation:'<p><code>querySelector</code> finds an element. <code>#hello</code> matches the button’s id.</p><p><code>addEventListener</code> waits for a click and runs the function inside it.</p><p><code>textContent</code> changes the message’s text. Keep your greeting between matching quotes.</p>',takeaway:'You just connected all three.',summary:'HTML creates the button. CSS styles it. JavaScript makes it respond. Download your page to keep the result.'}
];
let current=0; const code={...initial}; const $=id=>document.getElementById(id);
// A separate origin and CSP keep preview scripts away from workspace data and network requests.
function compose({html,css,js},isolated=false){
 const csp=isolated?`<meta http-equiv="Content-Security-Policy" content="default-src 'none'; script-src 'unsafe-inline'; style-src 'unsafe-inline'; img-src data:; connect-src 'none'; form-action 'none'; base-uri 'none'">`:'';
 return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>My first page</title>${csp}<style>${css}</style></head><body>${html}<script>${js.replace(/<\/script/gi,'<\\/script')}<\/script></body></html>`;
}
function storeEditor(){code[lessons[current].key]=$('editor').value;}
function renderPreview(){ $('frame').srcdoc=compose(code,true); }
function switchStep(index){if(!Number.isInteger(index)||index<0||index>=lessons.length)throw new Error('Choose a recipe from 0 to 2.');storeEditor();current=index;const l=lessons[index];$('editor').value=code[l.key];$('step-label').textContent=`0${index+1} / ${l.name.toUpperCase()}`;$('file-name').textContent=l.location;$('lesson-title').textContent=l.title;$('lesson-description').textContent=l.description;$('task-text').textContent=l.task;$('editor-label').textContent=l.key.toUpperCase();$('editor-help').textContent=l.hint;$('explanation').innerHTML=l.explanation;$('takeaway-title').textContent=l.takeaway;$('takeaway-text').textContent=l.summary;$('feedback').textContent='';$('next').textContent=index===2?'Download page':'Next recipe';document.querySelectorAll('[data-step]').forEach((b,i)=>{b.classList.toggle('selected',i===index);if(i===index)b.setAttribute('aria-current','step');else b.removeAttribute('aria-current');});}
function run(){storeEditor();const l=lessons[current];let warning='';if(!code[l.key].trim())warning='This snippet is empty. Add some code or reset it to the example.';else if(l.key==='html'&&!/<h1[\s>]/i.test(code.html))warning='The recipe expects an <h1> heading. Add it back or try the reset example.';else if(l.key==='js'){try{new Function(code.js);}catch(e){warning=`Check your JavaScript: ${e.message}`;}}renderPreview();$('preview-state').textContent='Updated from your code';$('feedback').textContent=warning||'Preview updated. Compare it with your last version.';return {step:l.name,warning,updated:true};}
function download(){storeEditor();const blob=new Blob([compose(code)],{type:'text/html'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='my-first-page.html';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);$('feedback').textContent='Downloaded my-first-page.html. Open it in a browser to try your page.';}
document.querySelectorAll('[data-step]').forEach(b=>b.addEventListener('click',()=>switchStep(Number(b.dataset.step))));$('run').addEventListener('click',run);$('download').addEventListener('click',download);$('next').addEventListener('click',()=>current===2?download():switchStep(current+1));$('reset').addEventListener('click',()=>{$('editor').value=initial[lessons[current].key];run();});$('editor').addEventListener('keydown',e=>{if(e.key==='Enter'&&(e.metaKey||e.ctrlKey)){e.preventDefault();run();}});for(const size of ['desktop','mobile'])$(size).addEventListener('click',()=>{$('frame-wrap').style.width=size==='mobile'?'min(100%, 360px)':'100%';$('desktop').setAttribute('aria-pressed',String(size==='desktop'));$('mobile').setAttribute('aria-pressed',String(size==='mobile'));});
$('editor').value=code.html;switchStep(0);renderPreview();
if(document.modelContext?.registerTool){const lifecycle=new AbortController();try{Promise.resolve(document.modelContext.registerTool({name:'set_recipe_code',description:'Edit and run one HTML, CSS, or JavaScript recipe in the visible workspace.',inputSchema:{type:'object',properties:{step:{type:'integer',minimum:0,maximum:2},code:{type:'string',maxLength:50000}},required:['step','code'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute(input){if(!input||!Number.isInteger(input.step)||input.step<0||input.step>2||typeof input.code!=='string'||input.code.length>50000)throw new Error('Supply a recipe step from 0 to 2 and code under 50,000 characters.');switchStep(input.step);$('editor').value=input.code;return run();}},{signal:lifecycle.signal})).catch(()=>{});}catch{}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
